INSERT INTO categories (id, slug, name_en, name_si, description_en, description_si, sort_order) VALUES (1, 'editorial', 'Leadership desk', 'නායකත්ව මේසය', 'Messages from the Deputy Chief Secretary and the Director.', 'නියෝජ්‍ය ප්‍රධාන ලේකම්ගේ සහ අධ්‍යක්ෂගේ පණිවිඩ.', 1);
INSERT INTO categories (id, slug, name_en, name_si, description_en, description_si, sort_order) VALUES (2, 'training', 'Training programmes & workshops', 'පුහුණු වැඩසටහන් හා වැඩමුළු', 'Monthly courses, dates, target groups, outcomes and photographs.', 'මාසික පාඨමාලා, දිනයන්, ඉලක්ක කණ්ඩායම්, ප්‍රතිඵල සහ ඡායාරූප.', 2);
INSERT INTO categories (id, slug, name_en, name_si, description_en, description_si, sort_order) VALUES (3, 'language', 'Language & external courses', 'භාෂා හා බාහිර පාඨමාලා', 'Bhasha classes and bahira patamala delivered with external institutes.', 'භාෂා පන්ති සහ බාහිර ආයතන සමඟ පවත්වන බාහිර පාඨමාලා.', 3);
INSERT INTO categories (id, slug, name_en, name_si, description_en, description_si, sort_order) VALUES (4, 'scholarship', 'Foreign scholarships & training', 'විදේශ ශිෂ්‍යත්ව හා පුහුණුව', 'Progress of officers on overseas attachments.', 'විදේශ අනුයුක්තිවල නිලධාරීන්ගේ ප්‍රගතිය.', 4);
INSERT INTO categories (id, slug, name_en, name_si, description_en, description_si, sort_order) VALUES (5, 'milestones', 'Milestones & special events', 'සන්ධිස්ථාන හා විශේෂ අවස්ථා', 'Institutional achievements and strategic targets reached this month.', 'මෙම මාසයේ ආයතනික ජයග්‍රහණ සහ උපායමාර්ගික ඉලක්ක.', 5);
INSERT INTO categories (id, slug, name_en, name_si, description_en, description_si, sort_order) VALUES (6, 'creative', 'Creative corner', 'නිර්මාණ කොන', 'Staff writing, poetry, artwork and photography.', 'කාර්ය මණ්ඩල ලිපි, කවි, චිත්‍ර සහ ඡායාරූප.', 6);
INSERT INTO categories (id, slug, name_en, name_si, description_en, description_si, sort_order) VALUES (7, 'plans', 'Future plans & upcoming events', 'ඉදිරි සැලසුම් හා ඉදිරි අවස්ථා', 'What the Unit will run in the coming month.', 'ඉදිරි මාසයේ ඒකකය පවත්වන කටයුතු.', 7);
INSERT INTO magazines (id, slug, month, year, title_en, title_si, summary_en, summary_si, highlights_json, cover_path, status, published_at, created_at, updated_at, back_path, cover_copy_json) VALUES (1, '2026-10', 10, 2026, 'Service, practiced', 'පුහුණුවෙන් ප්‍රගතිය', 'October kept the Unit in the training rooms and on the road. Leadership clinics, language classes and two overseas attachments ran side by side, and every course closed with a dated commitment from the officers who attended.', 'ඔක්තෝබර් මාසය ඒකකය පුහුණු ශාලාවල සහ ක්ෂේත්‍රයේ රඳවා ගත්තේය. නායකත්ව සායන, භාෂා පන්ති සහ විදේශ අනුයුක්ති දෙකක් එකවර ඉදිරියට ගියේය. සෑම පාඨමාලාවක්ම නිලධාරීන්ගේ දින නියමිත ප්‍රතිඥාවකින් අවසන් විය.', '[{"en":"Six workshops closed with written divisional action points.","si":"වැඩමුළු සයක් අංශීය ලිඛිත ක්‍රියාකාරී සැලසුම් සමඟ අවසන් විය."},{"en":"Tamil, English and an external finance diploma continued without a break.","si":"දෙමළ, ඉංග්‍රීසි සහ බාහිර මූල්‍ය ඩිප්ලෝමාව නොනැවතී පැවතුණි."},{"en":"Officers in Singapore and Hyderabad sent their first progress notes.","si":"සිංගප්පූරුවේ සහ හයිද්‍රාබාද්හි නිලධාරීන් පළමු ප්‍රගති සටහන් එවූහ."}]', '/assets/covers/2026-10.svg', 'published', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO magazines (id, slug, month, year, title_en, title_si, summary_en, summary_si, highlights_json, cover_path, status, published_at, created_at, updated_at, back_path, cover_copy_json) VALUES (2, '2026-09', 9, 2026, 'After the rain', 'වැස්සෙන් පසු', 'September was a month of follow-up. The Unit went back to three divisions, kept the language rooms open, and published the field notes in this edition.', 'සැප්තැම්බර් පසු විපරමේ මාසයක් විය. ඒකකය අංශ තුනකට ආපසු ගියේය, භාෂා කාමර විවෘතව තබා ගත්තේය, සහ ක්ෂේත්‍ර සටහන් මෙම කලාපයේ පළ කළේය.', '[{"en":"Field notes from three divisions after the August clinics.","si":"අගෝස්තු සායනවලින් පසු අංශ තුනක ක්ෂේත්‍ර සටහන්."},{"en":"Language classes held their line through the rains.","si":"වැසි හරහා භාෂා පන්ති තම මඟ රැකගත්තේය."},{"en":"One officer began an overseas induction.","si":"නිලධාරියෙකු විදේශ හඳුන්වාදීමක් ආරම්භ කළේය."}]', '/assets/covers/2026-09.svg', 'published', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO magazines (id, slug, month, year, title_en, title_si, summary_en, summary_si, highlights_json, cover_path, status, published_at, created_at, updated_at, back_path, cover_copy_json) VALUES (3, '2026-08', 8, 2026, 'The long table', 'දිගු මේසය', 'August put facilitators and new officers at the same table. The Unit trained the people who will train others, and opened the year''s follow-up book.', 'අගෝස්තුව පහසුකම් සපයන්නන් සහ නව නිලධාරීන් එකම මේසයකට වාඩි කළේය. අන් අය පුහුණු කරන අය ඒකකය පුහුණු කළේය. වසරේ පසු විපරම් පොත විවෘත කළේය.', '[{"en":"Facilitators rehearsed the sessions they will lead.","si":"පහසුකම් සපයන්නන් තමන් මෙහෙයවන සැසි පෙරහුරු කළහ."},{"en":"A long-table induction for new clerks.","si":"නව ලිපිකරුවන් සඳහා දිගු මේස හඳුන්වාදීමක්."},{"en":"The follow-up book was opened.","si":"පසු විපරම් පොත විවෘත කළේය."}]', '/assets/covers/2026-08.svg', 'published', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO magazines (id, slug, month, year, title_en, title_si, summary_en, summary_si, highlights_json, cover_path, status, published_at, created_at, updated_at, back_path, cover_copy_json) VALUES (4, '2026-11', 11, 2026, 'The return', 'ආපසු ඒම', 'November will read the October promises on site. This issue is still in draft.', 'නොවැම්බර් ඔක්තෝබර් ප්‍රතිඥා ස්ථානයේදී කියවයි. මෙම කලාපය තවම කෙටුම්පතකි.', '[{"en":"Field reading of the October promise sheets.","si":"ඔක්තෝබර් ප්‍රතිඥා පත්‍ර ක්ෂේත්‍රයේදී කියවීම."},{"en":"Oral checks for the language rooms.","si":"භාෂා කාමර සඳහා වාචික පරීක්ෂණ."},{"en":"A home seminar for the Singapore attachment.","si":"සිංගප්පූරු අනුයුක්තය සඳහා ගෙදර සම්මන්ත්‍රණයක්."}]', '/uploads/1791529209765-62e73137.jpg', 'published', '2026-10-09 07:00:33', '2026-10-07 14:26:12', '2026-10-10 18:46:24', '/uploads/1791521377495-e4a07cfb.jpg', '{}');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (1, 2, 1, 1, 'A month of deliberate practice', 'සැලසුම් සහගත පුහුණුවේ මාසයක්', 'This month the Unit asked every course to end with a commitment a division can keep. Training is not a break from the work. It is the work, practiced in a room where colleagues can disagree and still leave with a date, a name and a next step.
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (2, 3, 1, 1, 'What this issue holds', 'මෙම කලාපයේ අන්තර්ගතය', 'The programmes desk occupies the next three pages. Language and overseas attachments follow. The creative corner belongs to the staff, and the last page is the month we are about to enter. If your division is named here, the date beside it is a date we will keep.', 'ඊළඟ පිටු තුන වැඩසටහන් අංශයටය. ඉන්පසු භාෂාව සහ විදේශ අනුයුක්ති ය. නිර්මාණ කොන කාර්ය මණ්ඩලයට අයත්ය. අවසාන පිටුව අප යන මාසයයි. ඔබේ අංශය මෙහි සඳහන් නම්, එහි දිනය අප රකින දිනයකි.', 'A short map of the pages that follow.', 'ඉදිරි පිටුවල කෙටි සිතියමක්.', 'published', 0, 2, 1, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (3, 4, 2, 1, 'Leadership for service delivery', 'සේවා ලබාදීම සඳහා නායකත්වය', 'The five-day clinic asked supervising officers to name one service that their division delays, and to say who will change it. Case work came from counter queues, permit files and field visits.
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (4, 10, 2, 1, 'Evidence for planning', 'සැලසුම් සඳහා සාක්ෂි', 'Participants brought a live target from their annual plan and reduced the evidence for it to a single page: the number, the source, the gap and the owner. Thirty-six briefs were accepted.', 'සහභාගිවන්නන් වාර්ෂික සැලසුමේ සජීවී ඉලක්කයක් ගෙනැවිත්, එහි සාක්ෂිය එක් පිටුවකට අඩු කළහ. සංඛ්‍යාව, මූලාශ්‍රය, හිඩැස සහ වගකීම දරන්නා එහි විය. සටහන් 36 ක් භාර ගන්නා ලදී.', 'Planning officers practised a one-page evidence brief.', 'සැලසුම් නිලධාරීන් එක් පිටුවක සාක්ෂි සටහනක් පුහුණු කළහ.', 'published', 0, 3, 1, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (5, 4, 2, 1, 'Frontline supervision', 'ඉදිරි පෙළ අධීක්ෂණය', 'Supervisors practised a fifteen-minute feedback conversation and left with a script in Sinhala or Tamil. Forty-eight officers attended across two batches, so the hall never became a lecture.', 'අධීක්ෂකවරුන් විනාඩි පහළොවක ප්‍රතිචාර සංවාදයක් පුහුණු කළ අතර සිංහලෙන් හෝ දෙමළෙන් පිටපතක් රැගෙන ගියහ. කණ්ඩායම් දෙකක් ලෙස නිලධාරීන් 48 දෙනෙකු සහභාගි වූ නිසා ශාලාව දේශනයක් බවට පත් නොවීය.', 'A two-day drill on feedback that staff can use the same week.', 'එම සතියේම කාර්ය මණ්ඩලයට භාවිත කළ හැකි ප්‍රතිචාර පිළිබඳ දින දෙකක අභ්‍යාසයක්.', 'published', 0, 3, 2, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (6, 10, 2, 1, 'Digital records for divisional secretariats', 'ප්‍රාදේශීය ලේකම් කාර්යාල සඳහා ඩිජිටල් වාර්තා', 'Clerks and assistant secretaries rebuilt one real folder from their office during the class. Fifty-five participants left with a naming sheet and a backup day written into the office routine.', 'ලිපිකරුවන් සහ සහකාර ලේකම්වරු පන්තිය තුළදී තම කාර්යාලයේ සැබෑ ෆෝල්ඩරයක් නැවත ගොඩනඟා ගත්හ. සහභාගිවන්නන් 55 දෙනෙකු නම් කිරීමේ පත්‍රිකාවක් සහ කාර්යාල පිළිවෙතට ලියූ උපස්ථ දිනයක් රැගෙන ගියහ.', 'File naming, shared folders and a weekly backup drill.', 'ගොනු නම් කිරීම, හවුල් ෆෝල්ඩර සහ සතිපතා උපස්ථ අභ්‍යාසය.', 'published', 0, 4, 0, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (7, 9, 5, 1, 'The resource room passed 1,200 titles', 'සම්පත් කාමරය මාතෘකා 1,200 පසු කළේය', 'On 17 October the resource room finished its new catalogue. Twelve hundred titles are now labelled by subject and language, and facilitators can reserve a shelf before a course begins. The count includes the Sinhala, Tamil and English collections.', 'ඔක්තෝබර් 17 වන දා සම්පත් කාමරය නව නාමාවලිය අවසන් කළේය. මාතෘකා එක්දහස් දෙසියයක් දැන් විෂය සහ භාෂාව අනුව ලේබල් කර ඇත. පාඨමාලාවක් ආරම්භයට පෙර පහසුකම් සපයන්නන්ට රාක්කයක් වෙන් කළ හැක. ගණනට සිංහල, දෙමළ සහ ඉංග්‍රීසි එකතුව ඇතුළත්ය.', 'A catalogued room, open to every course.', 'සෑම පාඨමාලාවකටම විවෘත, නාමාවලියක් සහිත කාමරයක්.', 'published', 1, 4, 3, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (8, 4, 2, 1, 'Ethics and the public file', 'ආචාරධර්මය සහ රාජ්‍ය ගොනුව', 'Thirty-eight officers worked through dilemmas drawn from procurement and leave. Each table wrote the rule it will apply when the same case returns. The papers stay with the Director.', 'නිලධාරීන් 38 දෙනෙකු ප්‍රසම්පාදන සහ නිවාඩු වලින් ගත් ගැටලු හරහා වැඩ කළහ. සෑම මේසයක්ම එම අවස්ථාව නැවත ආ විට යොදන රීතිය ලිව්වේය. ලිපි අධ්‍යක්ෂවරයා සතුව පවතී.', 'A quiet room, a real dilemma, a written stance.', 'නිහඬ කාමරයක්, සැබෑ ගැටලුවක්, ලිඛිත ස්ථාවරයක්.', 'published', 0, 4, 1, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (9, 10, 2, 1, 'Training of trainers', 'පුහුණුකරුවන් පුහුණු කිරීම', 'The cohort rehearsed openings, timing and a closing question. Each facilitator will lead one session in November under observation.', 'කණ්ඩායම ආරම්භ, කාලය සහ අවසන් ප්‍රශ්නය පෙරහුරු කළේය. සෑම පහසුකම් සපයන්නෙක්ම නොවැම්බර් මාසයේ නිරීක්ෂණය යටතේ එක් සැසියක් මෙහෙයවයි.', 'Twenty-eight facilitators rehearsed a ninety-minute session.', 'පහසුකම් සපයන්නන් 28 දෙනෙකු විනාඩි අනූවක සැසියක් පෙරහුරු කළහ.', 'published', 0, 4, 2, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (10, 5, 3, 1, 'Intermediate Tamil for provincial officers', 'පළාත් නිලධාරීන් සඳහා මධ්‍යම දෙමළ', 'The Bhasha class stayed with the sentences officers need at a counter: names, dates, missing documents and a polite refusal. Twenty-six learners completed the October block and will sit a short oral check in November.', 'භාෂා පන්තිය නිලධාරීන්ට කවුළුවකදී අවශ්‍ය වාක්‍යවල රැඳුණේය. නම්, දිනයන්, අඩු ලේඛන සහ ආචාරශීලී ප්‍රතික්ෂේපය. ඉගෙන ගන්නන් 26 දෙනෙකු ඔක්තෝබර් කොටස සම්පූර්ණ කළ අතර නොවැම්බර් මාසයේ කෙටි වාචික පරීක්ෂණයකට පෙනී සිටිති.', 'Counter language, not textbook chapters.', 'පෙළපොත් පරිච්ඡේද නොව, කවුළුවේ භාෂාව.', 'published', 0, 5, 0, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (11, 5, 3, 1, 'External diploma in public financial management', 'රාජ්‍ය මූල්‍ය කළමනාකරණය පිළිබඳ බාහිර ඩිප්ලෝමාව', 'The Saturday diploma continued with budgeting and audit trails. Eighteen officers remained on the register. The external faculty marked the first assignment; sixteen passed the threshold and two will resubmit in November.', 'සෙනසුරාදා ඩිප්ලෝමාව අයවැය සහ විගණන මඟ සමඟ ඉදිරියට ගියේය. නිලධාරීන් දහඅට දෙනෙකු ලේඛනයේ රැඳුණි. බාහිර පීඨය පළමු පැවරුම ලකුණු කළේය. දහසය දෙනෙකු සීමාව පසු කළ අතර දෙදෙනෙකු නොවැම්බර් මාසයේ නැවත භාර දෙති.', 'Bahira patamala, taught with an external institute.', 'බාහිර ආයතනයක් සමඟ උගන්වන බාහිර පාඨමාලාව.', 'published', 0, 5, 1, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (12, 11, 3, 1, 'English for official correspondence', 'රාජ්‍ය ලිපි හුවමාරුව සඳහා ඉංග්‍රීසි', 'Twenty learners rewrote one letter from their own desk. The class marked clarity, not ornament. Corrected copies were returned the same week.', 'ඉගෙන ගන්නන් විස්ස දෙනෙකු තම මේසයේ ලිපියක් නැවත ලිව්වේය. පන්තිය සලකුණු කළේ අලංකාරය නොව පැහැදිලිකමයි. නිවැරදි කළ පිටපත් එම සතියේම ආපසු ලබා දුන්නේය.', 'Letters, minutes and a clean subject line.', 'ලිපි, මිනිත්තු සහ පැහැදිලි මාතෘකා පේළියක්.', 'published', 0, 5, 2, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (13, 6, 4, 1, 'Singapore: a public policy attachment', 'සිංගප්පූරුව: රාජ්‍ය ප්‍රතිපත්ති අනුයුක්තය', 'The officer attached to the Civil Service College has completed the opening fortnight on policy design and citizen feedback. The first note home lists three practices worth testing in a divisional secretariat: a named case owner, a public queue time, and a Friday review that lasts thirty minutes.
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (14, 6, 4, 1, 'Hyderabad: administrative training', 'හයිද්‍රාබාද්: පරිපාලන පුහුණුව', 'Two officers began the short course on inter-agency coordination. Their weekly note confirms attendance and names the field visit scheduled for the first week of November. A debrief at MDTU will follow their return.', 'නිලධාරීන් දෙදෙනෙකු අන්තර් ආයතන සම්බන්ධීකරණය පිළිබඳ කෙටි පාඨමාලාව ආරම්භ කළහ. ඔවුන්ගේ සතිපතා සටහන පැමිණීම තහවුරු කරන අතර නොවැම්බර් පළමු සතියට යෙදූ ක්ෂේත්‍ර සංචාරය නම් කරයි. ආපසු පැමිණීමෙන් පසු ඒකකයේ සාකච්ඡාවක් පවත්වයි.', 'A short course at the Administrative Staff College.', 'පරිපාලන කාර්ය මණ්ඩල විද්‍යාලයේ කෙටි පාඨමාලාවක්.', 'published', 0, 6, 0, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (15, 7, 6, 1, 'Rain over the tank', 'වැව මත වැස්ස', 'The tank took the rain without comment,
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (16, 12, 6, 1, 'The clerk and the clock', 'ලිපිකරු සහ ඔරලෝසුව', 'There is a clock above the counter that nobody trusts and everybody looks at. The clerk I watched did not argue with it. She finished the person in front of her, then the next, and wrote the time only when the file was truly closed. It is a small discipline. It is also the whole service.', 'කවුළුවට ඉහළින් කිසිවෙකු විශ්වාස නොකරන, නමුත් හැමෝම බලන ඔරලෝසුවක් ඇත. මා නිරීක්ෂණය කළ ලිපිකරු එය සමඟ වාද කළේ නැත. ඇය ඉදිරිපිට සිටි පුද්ගලයා අවසන් කළා, ඊළඟට, ගොනුව සැබවින්ම වැසූ විට පමණක් වේලාව ලිව්වා. එය කුඩා විනයකි. එයම මුළු සේවාවයි.', 'A short note on staying to the end of a queue.', 'පෝලිමේ අවසානය දක්වා රැඳී සිටීම ගැන කෙටි සටහනක්.', 'published', 0, 6, 2, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (17, 7, 6, 1, 'After class, Kurunegala', 'පන්තියෙන් පසු, කුරුණෑගල', 'The chairs go back. The board is wiped. Somebody always leaves a promise sheet, and somebody always brings it to the office. These frames were made after the leadership clinic, when the hall had returned to its ordinary light.', 'පුටු ආපසු යයි. ලඝු පුවරුව මකනු ලැබේ. යමෙක් සැමවිටම ප්‍රතිඥා පත්‍රයක් තබයි. යමෙක් සැමවිටම එය කාර්යාලයට ගෙන එයි. නායකත්ව සායනයෙන් පසු, ශාලාව සාමාන්‍ය එළියට පැමිණි විට මෙම රාමු සෑදුණි.', 'Three frames from the evening the hall emptied.', 'ශාලාව හිස් වූ සවසේ රාමු තුනක්.', 'published', 0, 7, 0, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (18, 8, 7, 1, 'Leadership clinic, second sitting', 'නායකත්ව සායනය, දෙවන වාරය', 'A second sitting opens for divisions that could not release staff in October. The same promise sheet will be used, so the November report can read both groups together.', 'ඔක්තෝබර් මාසයේ කාර්ය මණ්ඩලය මුදා ගැනීමට නොහැකි වූ අංශ සඳහා දෙවන වාරයක් විවෘත වේ. එම ප්‍රතිඥා පත්‍රයම භාවිත වන නිසා නොවැම්බර් වාර්තාවට කණ්ඩායම් දෙකම එකට කියවිය හැක.', '3–5 November, for officers who missed October.', 'නොවැම්බර් 3–5, ඔක්තෝබර් මඟ හැරුණු නිලධාරීන් සඳහා.', 'published', 0, 8, 0, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (19, 8, 7, 1, 'Field visit to Puttalam', 'පුත්තලම ක්ෂේත්‍ර සංචාරය', 'The Director and two training officers will sit with three divisions and compare the promise sheet with the counter as it actually runs.', 'අධ්‍යක්ෂවරයා සහ පුහුණු නිලධාරීන් දෙදෙනෙකු අංශ තුනක් සමඟ වාඩි වී, ප්‍රතිඥා පත්‍රය සැබෑ කවුළුව සමඟ සසඳයි.', '12 November, to read the October promises on site.', 'නොවැම්බර් 12, ඔක්තෝබර් ප්‍රතිඥා ස්ථානයේදී කියවීමට.', 'published', 0, 8, 1, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (20, 8, 7, 1, 'Bhasha oral assessment', 'භාෂා වාචික ඇගයීම', 'Tamil and English learners sit a ten-minute oral check. Results return to their heads of office with one recommended next class, not a rank list.', 'දෙමළ සහ ඉංග්‍රීසි ඉගෙන ගන්නන් විනාඩි දහයක වාචික පරීක්ෂණයකට පෙනී සිටිති. ප්‍රතිඵල ශ්‍රේණි ලැයිස්තුවක් නොව, නිර්දේශිත ඊළඟ පන්තියක් සමඟ කාර්යාල ප්‍රධානීන් වෙත යයි.', '18–19 November, language room.', 'නොවැම්බර් 18–19, භාෂා කාමරය.', 'published', 0, 8, 2, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (21, 2, 1, 2, 'Go back and look', 'ආපසු ගොස් බලන්න', 'We promised in August that training would return to the divisions that hosted it. September kept that promise. The notes in this issue were written after the visit, not before the certificate.', 'පුහුණුව සත්කාරකත්වය දැරූ අංශවලට ආපසු යන බව අප අගෝස්තුවේ පොරොන්දු වූයෙමු. සැප්තැම්බර් එම පොරොන්දුව රැකීය. මෙම කලාපයේ සටහන් සංචාරයෙන් පසු ලියූ ඒවාය. සහතිකයට පෙර නොවේ.', 'A course is finished only when the division has been seen again.', 'අංශය නැවත දුටු විට පමණක් පාඨමාලාව අවසන් වේ.', 'published', 0, 2, 0, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (22, 3, 1, 2, 'How to read the notes', 'සටහන් කියවන ආකාරය', 'Where a division is named, the date beside it is the day we will ask again. Please read the notes that way.', 'අංශයක් නම් කර ඇති තැන, එහි දිනය අප නැවත අසන දිනයයි. කරුණාකර සටහන් එසේ කියවන්න.', 'Dates first, then names.', 'පළමුව දිනයන්, ඉන්පසු නම්.', 'published', 0, 2, 1, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (23, 4, 2, 2, 'Return visit to Kuliyapitiya', 'කුලියාපිටියට ආපසු සංචාරය', 'Return visit to Kuliyapitiya ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'කුලියාපිටියට ආපසු සංචාරය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'The August promise, read at the counter.', 'අගෝස්තු ප්‍රතිඥාව කවුළුවේදී කියවීය.', 'published', 1, 3, 0, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (24, 10, 2, 2, 'Records clinic, second room', 'වාර්තා සායනය, දෙවන කාමරය', 'Records clinic, second room ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'වාර්තා සායනය, දෙවන කාමරය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'A smaller room, the same folder discipline.', 'කුඩා කාමරයක්, එම ගොනු විනයම.', 'published', 0, 3, 1, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (25, 4, 2, 2, 'Supervision refresher', 'අධීක්ෂණ නැවුම් කිරීම', 'Supervision refresher ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'අධීක්ෂණ නැවුම් කිරීම මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'One afternoon, one conversation, practised twice.', 'එක් දහවලක්, එක් සංවාදයක්, දෙවරක් පුහුණු කළේය.', 'published', 0, 3, 2, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (26, 10, 2, 2, 'Induction for new clerks', 'නව ලිපිකරුවන් සඳහා හඳුන්වාදීම', 'Induction for new clerks ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'නව ලිපිකරුවන් සඳහා හඳුන්වාදීම මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'The first week, taught by last year’s cohort.', 'පළමු සතිය, පසුගිය වසරේ කණ්ඩායම උගන්වයි.', 'published', 0, 4, 0, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (27, 9, 5, 2, 'Follow-up register opened', 'පසු විපරම් ලේඛනය විවෘත විය', 'Follow-up register opened ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'පසු විපරම් ලේඛනය විවෘත විය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'Every course now has a return date.', 'සෑම පාඨමාලාවකටම දැන් ආපසු දිනයක් ඇත.', 'published', 1, 4, 1, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (28, 5, 3, 2, 'Tamil through the rains', 'වැසි හරහා දෙමළ', 'Tamil through the rains ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'වැසි හරහා දෙමළ මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'Attendance held at twenty-four.', 'පැමිණීම විසිහතරේ රැඳුණි.', 'published', 0, 4, 2, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (29, 11, 3, 2, 'External writing seminar', 'බාහිර ලේඛන සම්මන්ත්‍රණය', 'External writing seminar ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'බාහිර ලේඛන සම්මන්ත්‍රණය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'Bahira patamala with a visiting lecturer.', 'ආගන්තුක කථිකාචාර්යවරයෙකු සමඟ බාහිර පාඨමාලාව.', 'published', 0, 4, 3, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (30, 6, 4, 2, 'Overseas induction week', 'විදේශ හඳුන්වාදීමේ සතිය', 'Overseas induction week ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'විදේශ හඳුන්වාදීමේ සතිය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'One officer began pre-departure briefing.', 'නිලධාරියෙකු පිටත්වීමට පෙර හඳුන්වාදීම ආරම්භ කළේය.', 'published', 1, 5, 0, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (31, 7, 6, 2, 'A note from the veranda', 'ඉස්තෝප්පුවෙන් සටහනක්', 'The rain stopped at the gate and not before. We dried the register on the veranda and nobody complained. There are days when the work is simply to keep the paper usable. This was one of them.', 'වැස්ස ගේට්ටුවේ නතර වූයේය. ඊට පෙර නොවේ. අපි ඉස්තෝප්පුවේ ලේඛනය වේලා ගත්තෙමු. කිසිවෙකු පැමිණිලි කළේ නැත. සමහර දිනවල කාර්යය නම් කඩදාසිය භාවිත කළ හැකි ලෙස තබා ගැනීමයි. මෙය එවැනි දිනයක් විය.', 'Staff writing after the field visit.', 'ක්ෂේත්‍ර සංචාරයෙන් පසු කාර්ය මණ්ඩල ලිවීම.', 'published', 0, 5, 1, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (32, 12, 6, 2, 'Three roads after rain', 'වැස්සෙන් පසු මාර්ග තුනක්', 'Three roads after rain ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'වැස්සෙන් පසු මාර්ග තුනක් මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'Photographs from the return journey.', 'ආපසු මගේ ඡායාරූප.', 'published', 0, 6, 0, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (33, 8, 7, 2, 'October leadership clinic', 'ඔක්තෝබර් නායකත්ව සායනය', 'October leadership clinic ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'ඔක්තෝබර් නායකත්ව සායනය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'The sitting that became this month’s cover story.', 'මෙම මාසයේ පිටකවර කතාව බවට පත් වාරය.', 'published', 0, 7, 0, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (34, 8, 7, 2, 'Catalogue weekend', 'නාමාවලි සති අන්තය', 'Catalogue weekend ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'නාමාවලි සති අන්තය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'The resource room count, scheduled.', 'සම්පත් කාමර ගණනය, යොදා ඇත.', 'published', 0, 7, 1, 9, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (35, 2, 1, 3, 'Teach the teachers first', 'පළමුව ගුරුවරුන් උගන්වන්න', 'August was given to the facilitators. If they are unsure, the room is unsure. The long table in this issue is not a metaphor. It is the table we actually set.', 'අගෝස්තුව පහසුකම් සපයන්නන්ට ලබා දුන්නෙමු. ඔවුන් අවිනිශ්චිත නම් කාමරය අවිනිශ්චිතය. මෙම කලාපයේ දිගු මේසය උපමාවක් නොවේ. අප සැබවින්ම යෙදූ මේසයයි.', 'A unit is only as steady as the people who hold the room.', 'කාමරය දරන අය තරම්ම ඒකකය ස්ථිරය.', 'published', 0, 2, 0, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (36, 3, 1, 3, 'A book of return dates', 'ආපසු දිනයන්ගේ පොතක්', 'We opened a book of return dates. Nothing in it is ornamental. If a course is listed, someone will go back.', 'අප ආපසු දිනයන්ගේ පොතක් විවෘත කළෙමු. එහි කිසිවක් අලංකාරය සඳහා නොවේ. පාඨමාලාවක් ලැයිස්තුගත නම්, යමෙක් ආපසු යයි.', 'Every course now owes the Unit a visit.', 'සෑම පාඨමාලාවක්ම දැන් ඒකකයට සංචාරයක් ණයයි.', 'published', 0, 2, 1, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (37, 10, 2, 3, 'The facilitators’ table', 'පහසුකම් සපයන්නන්ගේ මේසය', 'The facilitators’ table ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'පහසුකම් සපයන්නන්ගේ මේසය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'Twenty-four people rehearsed the year.', 'පුද්ගලයින් විසිහතර දෙනෙකු වසර පෙරහුරු කළහ.', 'published', 1, 3, 0, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (38, 4, 2, 3, 'New clerks at the long table', 'දිගු මේසයේ නව ලිපිකරුවන්', 'New clerks at the long table ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'දිගු මේසයේ නව ලිපිකරුවන් මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'Induction without a lecture.', 'දේශනයක් නැති හඳුන්වාදීම.', 'published', 0, 3, 1, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (39, 9, 5, 3, 'Follow-up book, first entries', 'පසු විපරම් පොත, පළමු ඇතුළත් කිරීම්', 'Follow-up book, first entries ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'පසු විපරම් පොත, පළමු ඇතුළත් කිරීම් මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'Twelve courses now have a return date.', 'පාඨමාලා දොළහකට දැන් ආපසු දිනයක් ඇත.', 'published', 1, 3, 2, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (40, 5, 3, 3, 'Bhasha, opening term', 'භාෂා, ආරම්භක වාරය', 'Bhasha, opening term ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'භාෂා, ආරම්භක වාරය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'Tamil and English rooms reopened.', 'දෙමළ සහ ඉංග්‍රීසි කාමර නැවත විවෘත විය.', 'published', 0, 4, 0, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (41, 6, 4, 3, 'Pre-departure panel', 'පිටත්වීමට පෙර මණ්ඩලය', 'Pre-departure panel ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'පිටත්වීමට පෙර මණ්ඩලය මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'Candidates briefed before nomination.', 'නම් කිරීමට පෙර අපේක්ෂකයන්ට හඳුන්වා දුන්නේය.', 'published', 0, 4, 1, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (42, 12, 6, 3, 'Names around a table', 'මේසය වටා නම්', 'Somebody has to know where the extra chairs are. Somebody has to spell the names as they are spoken, not as the form prefers. The long table works because those somebodies arrived early.', 'අමතර පුටු ඇත්තේ කොහේදැයි යමෙක් දැන සිටිය යුතුය. නම් උච්චාරණය වන පරිදි, පෝරමය කැමති පරිදි නොව, යමෙක් ලිවිය යුතුය. දිගු මේසය ක්‍රියා කරන්නේ එම අය ඉක්මනින් පැමිණි නිසාය.', 'A piece for the people who pour the tea.', 'තේ වත් කරන අය සඳහා ලිපියක්.', 'published', 0, 4, 2, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (43, 7, 6, 3, 'Chairs in a row', 'පේළියට පුටු', 'Chairs in a row ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'පේළියට පුටු මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'A photograph before anyone sat down.', 'කිසිවෙකු වාඩි වීමට පෙර ඡායාරූපයක්.', 'published', 0, 4, 3, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (44, 8, 7, 3, 'September field returns', 'සැප්තැම්බර් ක්ෂේත්‍ර ආපසු ඒම', 'September field returns ran for provincial staff this month. Officers left with one written action for their division and a date to report it back to the Unit.', 'සැප්තැම්බර් ක්ෂේත්‍ර ආපසු ඒම මෙම මාසයේ පළාත් නිලධාරීන් සඳහා පවත්වන ලදී. නිලධාරීන් තම අංශය සඳහා ලිඛිත ක්‍රියාවක් සහ එය ඒකකයට වාර්තා කිරීමේ දිනයක් රැගෙන ගියහ.', 'The visits this issue has now recorded.', 'මෙම කලාපය දැන් වාර්තා කර ඇති සංචාර.', 'published', 0, 5, 0, 8, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (45, 4, 2, 4, 'Reading the promises in Puttalam', 'පුත්තලම ප්‍රතිඥා කියවීම', 'Three divisions will be visited on 12 November. This note proposes the questions: Is the promise on the wall? Who owns it this week? What slipped?', 'නොවැම්බර් 12 වන දා අංශ තුනක් බැලීමට නියමිතය. මෙම සටහන ප්‍රශ්න යෝජනා කරයි. ප්‍රතිඥාව බිත්තියේ තිබේද? මෙම සතියේ එය අයිති කාටද? මඟ හැරුණේ කුමක්ද?', 'What the October sheets look like at the counter.', 'ඔක්තෝබර් පත්‍ර කවුළුවේදී පෙනෙන ආකාරය.', 'published', 1, 2, 0, 11, 2026, '', '2026-10-07 14:26:12', '2026-10-09 03:23:57', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (46, 5, 3, 4, 'Oral check design', 'වාචික පරීක්ෂණ සැලසුම', 'The oral check uses four counter sentences. Assessors mark whether the officer can finish the sentence with the citizen, not whether the grammar is ornate.', 'වාචික පරීක්ෂණය කවුළු වාක්‍ය හතරක් භාවිත කරයි. විභාගකයින් සලකුණු කරන්නේ නිලධාරියාට පුරවැසියා සමඟ වාක්‍යය අවසන් කළ හැකිද යන්නයි. ව්‍යාකරණය අලංකාරද යන්න නොවේ.', 'Ten minutes, no rank list.', 'විනාඩි දහයයි, ශ්‍රේණි ලැයිස්තුවක් නැත.', 'published', 1, 2, 2, 11, 2026, '', '2026-10-07 14:26:12', '2026-10-09 03:23:59', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (47, 6, 4, 4, 'Home seminar for Singapore', 'සිංගප්පූරුව සඳහා ගෙදර සම්මන්ත්‍රණය', 'The attached officer will join by video for forty minutes. The home team will choose one of the three practices and name a division willing to test it in December.', 'අනුයුක්ත නිලධාරියා විනාඩි හතළිහක් වීඩියෝ මගින් එකතු වේ. ගෙදර කණ්ඩායම පිළිවෙත් තුනෙන් එකක් තෝරා, දෙසැම්බර් මාසයේ එය අත්හදා බලන අංශයක් නම් කරයි.', '20 November, three practices to test.', 'නොවැම්බර් 20, අත්හදා බැලීමට පිළිවෙත් තුනක්.', 'published', 1, 3, 0, 11, 2026, '', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (48, 7, 6, 4, 'The second sitting', 'දෙවන වාරය', 'Coming late is not the same as being absent. The second sitting of the leadership clinic should say that on the first morning, before anybody apologises.', 'ප්‍රමාදව ඒම නොපැමිණීම නොවේ. නායකත්ව සායනයේ දෙවන වාරය එය පළමු උදෑසන කිව යුතුය. කිසිවෙකු සමාව ඉල්ලීමට පෙර.', 'A paragraph for the officers who come late to the year.', 'වසරට ප්‍රමාදව එන නිලධාරීන් සඳහා ඡේදයක්.', 'published', 0, 3, 1, 11, 2026, '', '2026-10-07 14:26:12', '2026-10-09 03:23:59', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (49, 4, 2, 4, 'Notes still being checked', 'තවම පරීක්ෂා වෙමින් පවතින සටහන්', 'Attendance for the second leadership sitting is not final. This draft will be submitted when the nomination list closes.', 'දෙවන නායකත්ව වාරයේ පැමිණීම තවම අවසන් නැත. නම් කිරීමේ ලැයිස්තුව වැසෙන විට මෙම කෙටුම්පත ඉදිරිපත් කරනු ලැබේ.', 'A draft, not yet offered to the editor.', 'කෙටුම්පතක්, තවම සංස්කාරකවරයාට ලබා දී නැත.', 'published', 0, 2, 1, 11, 2026, '', NULL, '2026-10-09 03:24:31', '2026-10-07 14:26:12', '2026-10-10 18:43:48', '', '');
INSERT INTO articles (id, user_id, category_id, magazine_id, title_en, title_si, body_en, body_si, excerpt_en, excerpt_si, status, featured, page_number, sort_order, target_month, target_year, reviewer_notes, submitted_at, reviewed_at, created_at, updated_at, byline_en, byline_si) VALUES (50, 4, 2, NULL, 'An unverified headcount', 'තහවුරු නොකළ සංඛ්‍යාවක්', 'This note claimed sixty participants. The register in the office shows forty-two for that clinic. It should not run until the two numbers agree.', 'මෙම සටහන සහභාගිවන්නන් හැටක් කියා සිටියේය. කාර්යාලයේ ලේඛනය එම සායනය සඳහා හතළිස් දෙදෙනෙකු පෙන්වයි. සංඛ්‍යා දෙක එකඟ වන තුරු එය යා නොහැක.', 'Returned to the author.', 'කතුවරයා වෙත ආපසු යවන ලදී.', 'approved', 0, NULL, 0, 10, 2026, '', '2026-10-07 14:26:12', '2026-10-09 03:24:31', '2026-10-07 14:26:12', '2026-10-09 03:24:31', '', '');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (1, 3, '2026-10-06', '2026-10-10', 'Divisional supervising officers', 'ප්‍රාදේශීය අධීක්ෂණ නිලධාරීන්', 'MDTU hall, Kurunegala', 'කළමනාකරණ සංවර්ධන පුහුණු ඒකක ශාලාව, කුරුණෑගල', 42, 'Eight divisions filed a dated service promise.', 'අංශ අටක් දින නියමිත සේවා ප්‍රතිඥාවක් භාර දුන්නේය.', '{"sessions":5,"hours":30,"satisfaction":94}');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (2, 4, '2026-10-14', '2026-10-15', 'Planning and development officers', 'සැලසුම් හා සංවර්ධන නිලධාරීන්', 'Provincial Council training room', 'පළාත් සභා පුහුණු කාමරය', 36, 'Thirty-six evidence briefs filed with the Unit.', 'සාක්ෂි සටහන් 36 ක් ඒකකයට භාර දුන්නේය.', '{"sessions":2,"hours":12,"satisfaction":91}');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (3, 5, '2026-10-20', '2026-10-21', 'Office heads and supervisors', 'කාර්යාල ප්‍රධානීන් සහ අධීක්ෂකවරු', 'MDTU hall, Kurunegala', 'කළමනාකරණ සංවර්ධන පුහුණු ඒකක ශාලාව, කුරුණෑගල', 48, 'Each supervisor kept a feedback script.', 'සෑම අධීක්ෂකයෙක්ම ප්‍රතිචාර පිටපතක් රඳවා ගත්තේය.', '{"sessions":4,"hours":14,"satisfaction":90}');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (4, 6, '2026-10-22', '2026-10-23', 'Divisional secretariat staff', 'ප්‍රාදේශීය ලේකම් කාර්යාල කාර්ය මණ්ඩලය', 'Computer lab, MDTU', 'පරිගණක විද්‍යාගාරය, කළමනාකරණ සංවර්ධන පුහුණු ඒකකය', 55, 'Fifty-five offices adopted a backup day.', 'කාර්යාල 55 ක් උපස්ථ දිනයක් අනුගමනය කළේය.', '{"sessions":2,"hours":12,"satisfaction":93}');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (5, 7, '2026-10-17', '2026-10-17', 'All facilitators and course clerks', 'සියලු පහසුකම් සපයන්නන් සහ පාඨමාලා ලිපිකරුවන්', 'MDTU resource room', 'කළමනාකරණ සංවර්ධන පුහුණු ඒකක සම්පත් කාමරය', 18, 'Catalogue opened for reservation.', 'වෙන්කිරීම සඳහා නාමාවලිය විවෘත විය.', '{"sessions":1,"hours":3,"satisfaction":96}');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (6, 8, '2026-10-27', '2026-10-27', 'Staff grade officers', 'කාර්ය මණ්ඩල ශ්‍රේණියේ නිලධාරීන්', 'MDTU hall, Kurunegala', 'කළමනාකරණ සංවර්ධන පුහුණු ඒකක ශාලාව, කුරුණෑගල', 38, 'Table papers filed with the Director.', 'මේස සටහන් අධ්‍යක්ෂවරයා වෙත භාර දුන්නේය.', '{"sessions":1,"hours":6,"satisfaction":92}');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (7, 9, '2026-10-29', '2026-10-30', 'Internal facilitators', 'අභ්‍යන්තර පහසුකම් සපයන්නන්', 'MDTU hall, Kurunegala', 'කළමනාකරණ සංවර්ධන පුහුණු ඒකක ශාලාව, කුරුණෑගල', 28, 'November observation roster confirmed.', 'නොවැම්බර් නිරීක්ෂණ ලැයිස්තුව තහවුරු විය.', '{"sessions":2,"hours":12,"satisfaction":95}');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (8, 10, '2026-10-01', '2026-10-29', 'Officers serving Tamil-speaking divisions', 'දෙමළ කතා කරන අංශවල සේවය කරන නිලධාරීන්', 'Language room, MDTU', 'භාෂා කාමරය, කළමනාකරණ සංවර්ධන පුහුණු ඒකකය', 26, 'October block complete. Oral check set for November.', 'ඔක්තෝබර් කොටස සම්පූර්ණයි. වාචික පරීක්ෂණය නොවැම්බර් සඳහා යෙදිණි.', '{"sessions":8,"hours":16,"satisfaction":93}');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (9, 11, '2026-10-04', '2026-10-25', 'Accounts and planning staff', 'ගිණුම් හා සැලසුම් කාර්ය මණ්ඩලය', 'External faculty, weekend classroom', 'බාහිර පීඨය, සති අන්ත පන්ති කාමරය', 18, 'Sixteen assignments passed the first threshold.', 'පැවරුම් දහසයක් පළමු සීමාව පසු කළේය.', '{"sessions":4,"hours":16,"satisfaction":88}');
INSERT INTO programs (id, article_id, start_date, end_date, target_group_en, target_group_si, venue_en, venue_si, participants, outcomes_en, outcomes_si, metrics_json) VALUES (10, 12, '2026-10-08', '2026-10-29', 'Officers who draft English letters', 'ඉංග්‍රීසි ලිපි කෙටුම්පත් කරන නිලධාරීන්', 'Language room, MDTU', 'භාෂා කාමරය, කළමනාකරණ සංවර්ධන පුහුණු ඒකකය', 20, 'Twenty letters returned with corrections.', 'නිවැරදි කිරීම් සහිත ලිපි විස්සක් ආපසු ලබා දුන්නේය.', '{"sessions":4,"hours":8,"satisfaction":90}');
